function adjustedKit(c:Row):Kit{
 const base=kits[c.style],adjustment=identityAdjustments[c.id];
 if(!adjustment)return base;
 const moves=base.moves.map((move,index)=>({...move,...adjustment.moves?.[index as 0|1|2]})) as Kit['moves'];
 return {...base,...adjustment.trait,basic:adjustment.basic??base.basic,moves};
}

